var limit = 20;
var p = Math.max(1, Number(page || 1));
var base = String(basicUrl || "https://btsearch.love").replace(/\/+$/, "");
var params = {
    keyword: String(s || ""),
    limit: String(limit),
    offset: String((p - 1) * limit),
    mode: "",
    time: "",
    sort: "size",
    sort_type: "desc",
    size: ""
};

function enc(v) {
    return encodeURIComponent(String(v === undefined || v === null ? "" : v));
}
function cleanText(v) {
    return String(v || "")
        .replace(/<[^>]+>/g, "")
        .replace(/&nbsp;/gi, " " )
        .replace(/&amp;/gi, "&")
        .replace(/&lt;/gi, "<")
        .replace(/&gt;/gi, ">")
        .replace(/&#39;/gi, "'")
        .replace(/&quot;/gi, "\"")
        .replace(/\s+/g, " " )
        .trim();
}
function randomNonce(len) {
    var chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    var out = "";
    for (var i = 0; i < len; i++) out += chars.charAt(Math.floor(Math.random() * chars.length));
    return out;
}

var timestamp = String(Math.floor(Date.now() / 1000));
var nonce = randomNonce(8);
var parts = ["timestamp=" + timestamp, "nonce=" + nonce];
var keys = Object.keys(params);
for (var i = 0; i < keys.length; i++) parts.push(keys[i] + "=" + params[keys[i]]);
parts.sort();
var sign = md5(parts.join("&") + "&key=long2ice").toUpperCase();

var query = [];
for (var j = 0; j < keys.length; j++) query.push(enc(keys[j]) + "=" + enc(params[keys[j]]));
var apiUrl = base + "/api/search?" + query.join("&");
var referer = base + "/search?keyword=" + enc(params.keyword);

var text = fetch(apiUrl, {
    headers: {
        "Accept": "application/json, text/plain, */*",
        "Referer": referer,
        "User-Agent": "Mozilla/5.0 (Linux; Android 16) AppleWebKit/537.36 Chrome/128.0 Mobile Safari/537.36",
        "x-timestamp": timestamp,
        "x-nonce": nonce,
        "x-sign": sign
    },
    timeout: 12000
});

var obj;
try {
    obj = JSON.parse(text);
} catch (e) {
    throw new Error("BTSearch 返回不是有效 JSON");
}

var data = [];
if (obj && Array.isArray(obj.data)) data = obj.data;
else if (obj && obj.data && Array.isArray(obj.data.data)) data = obj.data.data;
else if (obj && Array.isArray(obj.items)) data = obj.items;
else throw new Error("BTSearch 返回结构变化");

var out = [];
for (var k = 0; k < data.length; k++) {
    var it = data[k] || {};
    var title = cleanText(it.name || it.title || "");
    var hash = String(it.hash || it.info_hash || "")
        .replace(/^magnet:\?xt=urn:btih:/i, "")
        .replace(/[^A-Za-z0-9]/g, "")
        .toUpperCase();
    if (!/^[A-F0-9]{40}$/.test(hash) && !/^[A-Z2-7]{32}$/.test(hash)) continue;

    var magnet = "magnet:?xt=urn:btih:" + hash;
    if (title) magnet += "&dn=" + encodeURIComponent(title);

    var files = Number(
        it.files_count !== undefined ? it.files_count :
        it.file_count !== undefined ? it.file_count :
        it.fileCount !== undefined ? it.fileCount :
        it.filesCount !== undefined ? it.filesCount :
        0
    ) || 0;

    var created = it.created_at || it.created_time || it.create_time || it.createTime || it.date || it.added_at || it.add_time || "";
    var size = Number(it.size || it.bytes || 0) || 0;
    var desc = [];
    if (files > 0) desc.push("文件 " + files);
    if (it.hot !== undefined) desc.push("热度 " + it.hot);

    out.push({
        title: title || hash,
        magnet: magnet,
        bytes: size,
        seeders: it.seeders === undefined ? -1 : Number(it.seeders || 0),
        peers: it.peers === undefined ? -1 : Number(it.peers || 0),
        date: String(created || ""),
        desc: desc.join(" · " )
    });
}
return out;
